        internal void TglSensorLogger_Checked(object sender, System.Windows.RoutedEventArgs e)
        {
            _sensorLogger.Enabled = true;
            AppLogger.Debug($"SensorLogger started: {_sensorLogger.CurrentFile}");
            if (FindName("TxtLoggerPath") is System.Windows.Controls.TextBlock tb)
                tb.Text = _sensorLogger.CurrentFile;
