        internal void ToggleEnduranceMode_Click(object sender, RoutedEventArgs e)
        {
            _enduranceModeOn = !_enduranceModeOn;
            _stressIntensityPct = _enduranceModeOn ? 80 : 100;

            if (_cpuStress.Running) _cpuStress.IntensityPct = _stressIntensityPct;
            _gpuStress.EnduranceMode = _enduranceModeOn;

            if (BtnEnduranceMode != null)
            {
                BtnEnduranceMode.Appearance = _enduranceModeOn
                    ? Wpf.Ui.Controls.ControlAppearance.Success
                    : Wpf.Ui.Controls.ControlAppearance.Secondary;
                if (_enduranceModeOn)
                    BtnEnduranceMode.Foreground = System.Windows.Media.Brushes.White;
                else
                    BtnEnduranceMode.SetResourceReference(System.Windows.Controls.Control.ForegroundProperty, "TextSecondaryBrush");
            }
            if (FindName("BtnEnduranceIcon") is System.Windows.Shapes.Path icon)
            {
                if (_enduranceModeOn)
                    icon.Fill = System.Windows.Media.Brushes.White;
                else
                    icon.SetResourceReference(System.Windows.Shapes.Shape.FillProperty, "TextSecondaryBrush");
            }
            if (FindName("TxtBtnEnduranceMode") is TextBlock tb)
                tb.Text = _enduranceModeOn ? "Long test: ON" : "Long test";

            // The "active" state is visible in the table too, next to CPU/GPU — the STRESS badge becomes ENDURANCE while the mode
            // is on (see UpdateStressTimers).
            ShowToast(_enduranceModeOn
                ? "Endurance mode ON — stress will run at a sustained 80% (long-duration testing)."
                : "Endurance mode OFF — stress runs at 100% again.",
                "", 2500);
        }

        private bool _keepAwakeActive = false;
        private void SyncSensorLoggerWithStress()
        {
            bool stressActive = _cpuStress.Running || _gpuStress.IsRunning;

            if (stressActive && !_keepAwakeActive)
            {
                _keepAwakeActive = true;
                var prevState = NativeMethods.SetThreadExecutionState(
                    NativeMethods.ES_CONTINUOUS | NativeMethods.ES_SYSTEM_REQUIRED);
                AppLogger.Debug($"KeepAwake: activated for stress test (prev state: 0x{prevState:X8})");
            }
            else if (!stressActive && _keepAwakeActive)
            {
                _keepAwakeActive = false;
                NativeMethods.SetThreadExecutionState(NativeMethods.ES_CONTINUOUS);
                AppLogger.Debug("KeepAwake: released (stress test ended)");
            }

            if (stressActive && !_sensorLogger.Enabled)
            {
                _sensorLogger.Enabled = true;
                _loggerAutoStarted = true;
                AppLogger.Debug($"SensorLogger auto-started (stress test): {_sensorLogger.CurrentFile}");
                if (FindName("TxtLoggerPath") is TextBlock tbAuto) tbAuto.Text = _sensorLogger.CurrentFile;
                if (FindName("TglSensorLogger") is System.Windows.Controls.Primitives.ToggleButton tgAuto)
                    tgAuto.IsChecked = true;
            }
            else if (!stressActive && _loggerAutoStarted)
            {
                _sensorLogger.Enabled = false;
                _loggerAutoStarted = false;
                AppLogger.Debug("SensorLogger auto-stopped (stress test ended)");
                if (FindName("TglSensorLogger") is System.Windows.Controls.Primitives.ToggleButton tgAuto2)
                    tgAuto2.IsChecked = false;
            }
        }

        internal void ToggleCpuStress_Click(object sender, RoutedEventArgs e)
        {
            if (_cpuStress.Running || _cpuStressWanted) StopCpuStress();
            else StartCpuStress();
        }

        /// <summary>Explicit, idempotent stop (never starts the test).</summary>
        private void StopCpuStress()
        {
            bool wasWanted = _cpuStressWanted;
            _cpuStressWanted = false;
            if (!_cpuStress.Running && !wasWanted) return;
            if (!_cpuStress.Running)
            {
                // stopped before it got to start: only restore the button
                SetStressButtonState(BtnStressCpu, TxtBtnStressCpu, iconPath: "M5,3 L19,12 L5,21 Z",
                    label: _LS("Stress", "CpuStressLabel"), styleKey: "GreenButtonStyle");
                if (FindName("CpuStressIndicator") is Border ind0) ind0.Visibility = Visibility.Collapsed;
                return;
            }
            _cpuStress.Stop();
            EndStressRun(gpu: false);
            SetStressButtonState(BtnStressCpu, TxtBtnStressCpu,
                iconPath: "M5,3 L19,12 L5,21 Z",
                label:    _LS("Stress", "CpuStressLabel"),
                styleKey: "GreenButtonStyle");
            if (FindName("CpuStressIndicator") is Border ind) ind.Visibility = Visibility.Collapsed;
            if (SettingsService.Current.AutoSnapshotOnStress) AutoSaveStressSnapshot("CPU");
            SetNavTaskBadge("TaskBadgeStress", _cpuStress.Running || _gpuStress.IsRunning);
            SyncSensorLoggerWithStress();
            UpdateStressBanner();
        }

        private bool _cpuStressWanted;   // requested by the user; stops a delayed start if Stop was pressed in the meantime

        /// <summary>
        /// The processor test: all threads but one, at minimum priority (StressCpu). The free thread keeps the interface and the
        /// sensor reads up to date; the load is 100 % on the test threads (80 % in Endurance).
        /// </summary>
        private void StartCpuWorkers(int workers)
        {
            _cpuStress.Start(workers, reserveCores: 1);
            AppLogger.Info("CPU stress: {0} threads (1 free), intensity={1}%", Math.Max(1, Math.Min(workers, Environment.ProcessorCount) - 1), _cpuStress.IntensityPct);
        }

        private void StartCpuStress()
        {
            if (_cpuStress.Running || _cpuStressWanted) return;
            _cpuStressWanted = true;
            int workers = Environment.ProcessorCount;
            _cpuStress.IntensityPct = _stressIntensityPct;
            // first the button changes ("Stop"), only then the load starts: the press shows immediately, without freezing
            SetStressButtonState(BtnStressCpu, TxtBtnStressCpu,
                iconPath: "M6,6 H18 V18 H6 Z",
                label:    _LS("Stress", "StopCpuStress"),
                styleKey: "RedButtonStyle", fillIcon: true);
            if (FindName("CpuStressIndicator") is Border ind) ind.Visibility = Visibility.Visible;
            Dispatcher.BeginInvoke(new Action(() =>
            {
                try
                {
                    if (!_cpuStressWanted) return;
                    StartCpuWorkers(workers);
                    BeginStressRun(gpu: false);
                    ApplyStressAutoStopIfNeeded();
                    SetNavTaskBadge("TaskBadgeStress", _cpuStress.Running || _gpuStress.IsRunning);
                    SyncSensorLoggerWithStress();
                    UpdateStressBanner();
                }
                catch (Exception ex) { AppLogger.Warning(ex, "StartCpuStress"); }
            }), System.Windows.Threading.DispatcherPriority.Background);
        }

        internal void ToggleGpuStress_Click(object sender, RoutedEventArgs e)
        {
            if (_gpuStress.IsRunning) StopGpuStress();
            else StartGpuStress();
        }

        // True while the UI shows the GPU test as running. Allows detecting an unexpected stop of the thread (driver error /
        // TDR) and bringing the UI back to the correct state.
        private bool _gpuStressUiRunning;
        private string? _psuFaultShown;

        private void StopGpuStress()
        {
            if (!_gpuStress.IsRunning && !_gpuStressUiRunning) return;
            _gpuStressUiRunning = false;
            _gpuStress.Stop();
            EndStressRun(gpu: true);
            // Timer: if it is still running after 3 s, warn
            var checkTimer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(3) };
            checkTimer.Tick += (_, _) => { checkTimer.Stop(); if (_gpuStress.IsRunning) ShowToastWarning(LanguageService.S("Msg", "GpuStressStillRunning")); };
            checkTimer.Start();
            SetStressButtonState(BtnStressGpu, TxtBtnStressGpu,
                iconPath: "M5,3 L19,12 L5,21 Z",
                label:    _LS("Stress", "GpuStressLabel"),
                styleKey: "GreenButtonStyle");
            if (GpuStressRunPanel != null) GpuStressRunPanel.Visibility = Visibility.Collapsed;
            _tempReader?.SetSensorMode(SMDWin.Services.LhmSensorMode.Full);
            ShowToast(_LS("Stress", "GpuStressStopped"), "");
            if (FindName("GpuStressIndicator") is Border gind) gind.Visibility = Visibility.Collapsed;
            if (SettingsService.Current.AutoSnapshotOnStress) AutoSaveStressSnapshot("GPU");
            SetNavTaskBadge("TaskBadgeStress", _cpuStress.Running || _gpuStress.IsRunning);
            SyncSensorLoggerWithStress();
            UpdateStressBanner();
        }

        private void StartGpuStress()
        {
            if (_gpuStress.IsRunning) return;
            _gpuStressUiRunning = true;
            SetStressButtonState(BtnStressGpu, TxtBtnStressGpu,
                iconPath: "M6,6 H18 V18 H6 Z",
                label:    _LS("Stress", "StopGpuStress"),
                styleKey: "RedButtonStyle", fillIcon: true);
            if (GpuStressRunPanel != null) GpuStressRunPanel.Visibility = Visibility.Visible;
            ShowToast(_LS("Stress", "GpuStressRunningWarning"), "🔥", 4000, ToastKind.Warning);
            if (FindName("GpuStressIndicator") is Border gind) gind.Visibility = Visibility.Visible;
            // the load starts after the interface has drawn the button (no freeze on press)
            Dispatcher.BeginInvoke(new Action(() =>
            {
                try
                {
                    if (!_gpuStressUiRunning) return;
                    _gpuStress.Start();
                    BeginStressRun(gpu: true);
                    ApplyStressAutoStopIfNeeded();
                    SetNavTaskBadge("TaskBadgeStress", _cpuStress.Running || _gpuStress.IsRunning);
                    SyncSensorLoggerWithStress();
                    UpdateStressBanner();
                }
                catch (Exception ex) { AppLogger.Warning(ex, "StartGpuStress"); }
            }), System.Windows.Threading.DispatcherPriority.Background);
        }

        /// <summary>Updates a stress toggle button: changes icon path, label text and style.
        /// Searches the LIVE content tree — the named TextBlock may be orphaned after
        /// ApplyLanguage/IconB rebuilds the button content.</summary>
        private void SetStressButtonState(
            System.Windows.Controls.Button? btn,
            System.Windows.Controls.TextBlock? txt,
            string iconPath, string label, string styleKey, bool fillIcon = false)
        {
            if (txt != null) txt.Text = label; // legacy named ref (may be orphaned — harmless)
            // test running = red "Stop" button (the common rule, SetStopLook); otherwise the usual button with the green icon
            bool running = styleKey == "RedButtonStyle";
            SetStopLook(btn, running, Wpf.Ui.Controls.ControlAppearance.Secondary);

            // Update icon Path AND TextBlock inside the button's LIVE content
            if (btn?.Content is System.Windows.Controls.StackPanel sp)
            {
                foreach (var child in sp.Children)
                {
                    if (child is System.Windows.Controls.Viewbox vb &&
                        vb.Child is System.Windows.Controls.Canvas cv)
                    {
                        foreach (var item in cv.Children)
                            if (item is System.Windows.Shapes.Path p)
                            {
                                // Fluent icon: the stop square is the filled variant, the bolt stays a bolt, the rest is "play"
                                string icon = iconPath.Contains("H18 V18") || iconPath.Contains("h12v12") ? "stop_filled"
                                            : iconPath.StartsWith("M5 2l") || iconPath.StartsWith("M13") ? "flash"
                                            : SMDWin.Services.FluentIcons.Has(iconPath) ? iconPath : "play";
                                p.Data = SMDWin.Services.FluentIcons.Get(icon);
                                p.Stroke = null;
                                // on the red background the icon takes the button text colour (white); green would disappear
                                if (running || fillIcon)
                                    p.SetBinding(System.Windows.Shapes.Shape.FillProperty,
                                        new System.Windows.Data.Binding(nameof(btn.Foreground)) { Source = btn });
                                else
                                    p.SetResourceReference(System.Windows.Shapes.Shape.FillProperty, "StatusOkBrush");
                                break;
                            }
                    }
                    else if (child is System.Windows.Controls.TextBlock liveTb)
                    {
                        liveTb.Text = label; // the actually-visible TextBlock
                    }
                }
            }
        }

        /// <summary>Show/hide the stress active banner and update per-type panels.</summary>
        private void UpdateStressBanner()
        {
            bool cpuOn = _cpuStress.Running;
            bool gpuOn = _gpuStress.IsRunning;
            bool ramDiskOn = _psuStress.IsRunning;

            if (StressActiveBanner != null)
                StressActiveBanner.Visibility = (cpuOn || gpuOn || ramDiskOn) ? Visibility.Visible : Visibility.Collapsed;

            if (CpuStressBannerPanel != null)
                CpuStressBannerPanel.Visibility = cpuOn ? Visibility.Visible : Visibility.Collapsed;

            if (GpuStressBannerPanel != null)
                GpuStressBannerPanel.Visibility = gpuOn ? Visibility.Visible : Visibility.Collapsed;

            UpdateStressPlanUi();   // the test bar (Start / Stop, locked choices)
        }

        private System.Windows.Threading.DispatcherTimer? _gpuStressTimer;
        private readonly float[] _gpuStressHistory = new float[60];
        private int _gpuStressIdx = 0;

        private void InitGpuStressTimer()
        {
            _gpuStressTimer = new System.Windows.Threading.DispatcherTimer
            {
                Interval = TimeSpan.FromSeconds(1)
            };
            _gpuStressTimer.Tick += (_, _) => UpdateGpuStressUI();
            _gpuStressTimer.Start();
        }

        private void UpdateGpuStressUI()
        {
            // the GPU stress thread stopped by itself (error / driver reset) while the UI shows it running — bring the UI back to
            // the correct state and show the reason.
            if (_gpuStressUiRunning && !_gpuStress.IsRunning)
            {
                string reason = _gpuStress.LastError;
                bool tdr = _gpuStress.DriverResetDetected;
                StopGpuStress();
                if (!string.IsNullOrEmpty(reason))
                    ShowToast((tdr ? _LS("Stress", "GpuDriverReset") : "GPU stress: ") + (tdr ? "" : reason),
                        "⚠", 9000, ToastKind.Warning);
            }

            // errors of the RAM/Disk threads in Max Load become visible (once per session)
            if (_psuStress.IsRunning)
            {
                string? fault = _psuStress.DiskFault ?? _psuStress.RamFault;
                if (fault != null && fault != _psuFaultShown)
                {
                    _psuFaultShown = fault;
                    ShowToast("Max Load: " + fault, "⚠", 9000, ToastKind.Warning);
                }
            }
            else _psuFaultShown = null;

            if (PanelStress?.Visibility != Visibility.Visible) return;

            // Pull GPU stats from TempReader
            var snap = _lastTempSnap;
            var load = GpuLoadNow;
            var temp = snap?.GpuTemp;
            var vram = snap?.GpuMemUsedMB;

            // ── Always update live GPU stats card (visible even without stress running) ──
            if (TxtGpuLiveLoad != null)
            {
                TxtGpuLiveLoad.Text = load.HasValue ? $"{load.Value:F0} %" : "— %";
                TxtGpuLiveLoad.Foreground = load.HasValue && load.Value > 85 ? _brRed
                    : load.HasValue && load.Value > 50 ? _brOrange : _brGreen;
            }
            if (TxtKpiGpuLoad != null)
            {
                TxtKpiGpuLoad.Text = load.HasValue ? $"{load.Value:F0}%" : "—";
                TxtKpiGpuLoad.ToolTip = load.HasValue ? null : "Sensor unavailable right now";
                if (load.HasValue)
                    TxtKpiGpuLoad.Foreground = load.Value > 80 ? _brRed : load.Value > 50 ? _brOrange : _brGreen;
                // GPU temp inline in the card header — with the unit, like the other place that writes it (UpdateStressTempLabel).
                if (TxtStressGpuTemp != null)
                    TxtStressGpuTemp.Text = snap?.GpuTemp.HasValue == true
                        ? $"{TempUnit.Fmt(snap.GpuTemp!.Value)}"
                        : "";
                TxtKpiGpuLoad.Foreground = load.HasValue && load.Value > 85 ? _brRed
                    : load.HasValue && load.Value > 50 ? _brOrange : _brGreen;
            }
            if (GpuLoadBar != null && load.HasValue)
            {
                double pct = Math.Min(1.0, load.Value / 100.0);
                var parent = GpuLoadBar.Parent as System.Windows.Controls.Border;
                if (parent != null) GpuLoadBar.Width = Math.Max(0, (parent.ActualWidth - 0) * pct);
            }
            if (TxtGpuLiveTemp != null)
            {
                TxtGpuLiveTemp.Text = temp.HasValue ? $"{TempUnit.Fmt(temp.Value, 0, true)}" : $"— {TempUnit.Symbol}";
                TxtGpuLiveTemp.Foreground = temp.HasValue && temp.Value > 85 ? _brRed
                    : temp.HasValue && temp.Value > 70 ? _brOrange : _brGreen;
            }
            if (GpuTempBar != null && temp.HasValue)
            {
                double pct = Math.Min(1.0, temp.Value / 110.0);
                var parent = GpuTempBar.Parent as System.Windows.Controls.Border;
                if (parent != null) GpuTempBar.Width = Math.Max(0, (parent.ActualWidth - 0) * pct);
            }
            if (TxtGpuLiveVram != null)
                TxtGpuLiveVram.Text = vram.HasValue ? $"{vram.Value:N0} MB" : "— MB";
            if (GpuVramBar != null && vram.HasValue)
            {
                double pct = Math.Min(1.0, vram.Value / 8192.0); // assume 8GB max
                var parent = GpuVramBar.Parent as System.Windows.Controls.Border;
                if (parent != null) GpuVramBar.Width = Math.Max(0, (parent.ActualWidth - 0) * pct);
            }
            if (TxtGpuPowerLive != null)
            {
                var pw = snap?.GpuPowerW;
                TxtGpuPowerLive.Text = pw.HasValue ? $"{pw.Value:F0} W" : "— W";
            }

            // ── Stress running: update dispatch/s and stress stats strip ──
            if (!_gpuStress.IsRunning) return;

            if (TxtGpuStressFps  != null) TxtGpuStressFps.Text  = _gpuStress.DispatchHz.ToString("N0");
            if (TxtGpuStressLoad != null)
            {
                TxtGpuStressLoad.Text = load.HasValue ? $"{load.Value:F0} %" : "— %";
                TxtGpuStressLoad.Foreground = load.HasValue && load.Value > 85 ? _brRed
                    : load.HasValue && load.Value > 60 ? _brOrange : _brGreen;
            }
            if (TxtGpuStressTemp != null)
            {
                TxtGpuStressTemp.Text = temp.HasValue ? $"{TempUnit.Fmt(temp.Value, 0, true)}" : $"— {TempUnit.Symbol}";
                TxtGpuStressTemp.Foreground = temp.HasValue && temp.Value > 85 ? _brRed
                    : temp.HasValue && temp.Value > 70 ? _brOrange : _brGreen;
            }
            if (TxtGpuStressVram != null)
                TxtGpuStressVram.Text = vram.HasValue ? $"{vram.Value:N0} MB" : "— MB";

            // Update banner stats (inline, no separate popup)
            if (TxtGpuStressBannerStats != null)
            {
                var parts = new System.Text.StringBuilder();
                if (load.HasValue) parts.Append($"{load.Value:F0}% load");
                if (temp.HasValue) { if (parts.Length > 0) parts.Append("  ·  "); parts.Append($"{TempUnit.Fmt(temp.Value)}"); }
                if (_gpuStress.DispatchHz > 0) { if (parts.Length > 0) parts.Append("  ·  "); parts.Append($"{_gpuStress.DispatchHz} fps"); }
                TxtGpuStressBannerStats.Text = parts.ToString();
            }
            if (TxtCpuStressBannerStats != null && _cpuStress.Running && _lastTempSnap != null)
            {
                var cpuLoad = CpuLoadNow;
                var cpuTemp = _lastTempSnap.CpuTemp;
                var parts = new System.Text.StringBuilder();
                if (cpuLoad.HasValue) parts.Append($"{cpuLoad.Value:F0}% load");
                if (cpuTemp.HasValue) { if (parts.Length > 0) parts.Append("  ·  "); parts.Append($"{TempUnit.Fmt(cpuTemp.Value)}"); }
                if (_lastTempSnap.CpuPowerW is float cpw && cpw > 0) { if (parts.Length > 0) parts.Append("  ·  "); parts.Append($"{cpw:F0} W"); }
                TxtCpuStressBannerStats.Text = parts.ToString();
            }

            float loadVal = load ?? 0f;
            _gpuStressHistory[_gpuStressIdx % 60] = loadVal;
            _gpuStressIdx++;
            DrawGpuStressChart();
        }

        private void DrawGpuStressChart()
        {
            var canvas = GpuStressChart;
            if (canvas == null) return;
            double w = canvas.ActualWidth, h = canvas.ActualHeight;
            if (!double.IsFinite(w) || !double.IsFinite(h) || w < 2 || h < 2) return;

            var color = WpfColor.FromRgb(249, 115, 22); // #F97316 orange
            int count = Math.Min(_gpuStressIdx, 60);
            int startIdx = _gpuStressIdx >= 60 ? _gpuStressIdx % 60 : 0;

            const double pL = 4, pR = 6, pT = 6, pB = 4;
            double cW = w - pL - pR, cH = h - pT - pB;

            var pts = new System.Collections.Generic.List<System.Windows.Point>();
            for (int i = 0; i < count; i++)
            {
                float v = _gpuStressHistory[(startIdx + i) % 60];
                double x = pL + (double)i / 59 * cW;
                double y = pT + cH - Math.Max(0, Math.Min(1, v / 100.0)) * cH;
                pts.Add(new System.Windows.Point(x, y));
            }
            if (pts.Count < 2) return;

            if (_gpuStressIdx == _drawnIdxGpuStress && Math.Abs(w - _drawnWGpuStress) < 1 && Math.Abs(h - _drawnHGpuStress) < 1) return;
            _drawnIdxGpuStress = _gpuStressIdx; _drawnWGpuStress = w; _drawnHGpuStress = h;

            if (!_dvCache.TryGetValue(canvas, out var dv))
            {
                dv = new DrawingVisual();
                _dvCache[canvas] = dv;
            }
            using (var dc = dv.RenderOpen())
            {
                // Fill
                var fillPf = new System.Windows.Media.PathFigure
                    { StartPoint = new System.Windows.Point(pts[0].X, pT + cH), IsClosed = true };
                fillPf.Segments.Add(new System.Windows.Media.LineSegment(pts[0], true));
                for (int pi = 1; pi < pts.Count; pi++)
                    fillPf.Segments.Add(new System.Windows.Media.LineSegment(pts[pi], true));
                fillPf.Segments.Add(new System.Windows.Media.LineSegment(
                    new System.Windows.Point(pts[pts.Count - 1].X, pT + cH), true));
                var fillPg = new System.Windows.Media.PathGeometry();
                fillPg.Figures.Add(fillPf);
                fillPg.Freeze();
                var fillBr = new System.Windows.Media.LinearGradientBrush(
                    WpfColor.FromArgb(55, color.R, color.G, color.B),
                    WpfColor.FromArgb(5,  color.R, color.G, color.B),
                    new System.Windows.Point(0, 0), new System.Windows.Point(0, 1));
                fillBr.Freeze();
                dc.DrawGeometry(fillBr, null, fillPg);

                // Line
                var linePg = BuildSmoothPath(pts);
                var pen = new System.Windows.Media.Pen(
                    new SolidColorBrush(color), 1.5);
                pen.Freeze();
                dc.DrawGeometry(null, pen, linePg);

                // Dot
                var dotBr = new SolidColorBrush(color); dotBr.Freeze();
                dc.DrawEllipse(dotBr, null, pts[pts.Count - 1], 3.5, 3.5);
            }

            RenderToCanvas(canvas, dv, w, h);
        }

        internal void GpuStressChart_SizeChanged(object sender,
            System.Windows.SizeChangedEventArgs e) => DrawGpuStressChart();

        // PSU Stress handler kept as compat stub (button is now hidden in XAML)
        internal void TogglePsuStress_Click(object sender, RoutedEventArgs e) { /* replaced by ToggleMaxLoad */ }

        internal void ToggleMaxLoad_Click(object sender, RoutedEventArgs e)
        {
            if (_cpuStress.Running || _gpuStress.IsRunning || _psuStress.IsRunning) StopAllStress();
            else StartMaxLoad();
        }

        /// <summary>Stops ALL running stress tests (CPU, GPU, RAM+Disk).
        /// Idempotent — if nothing runs, it does nothing (never starts a test).</summary>
        private void StopAllStress()
        {
            bool cpuOn = _cpuStress.Running;
            bool gpuOn = _gpuStress.IsRunning;
            bool ramDiskOn = _psuStress.IsRunning;
            if (!(cpuOn || gpuOn || ramDiskOn || _gpuStressUiRunning)) return;
            _gpuStressUiRunning = false;
            // Stop all
            if (cpuOn)
            {
                _cpuStress.Stop();
                SetStressButtonState(BtnStressCpu, TxtBtnStressCpu,
                    "M5,3 L19,12 L5,21 Z", _LS("Stress", "CpuStressLabel"), "GreenButtonStyle");
                if (FindName("CpuStressIndicator") is Border ci) ci.Visibility = Visibility.Collapsed;
            }
            if (gpuOn)
            {
                _gpuStress.Stop();
                SetStressButtonState(BtnStressGpu, TxtBtnStressGpu,
                    "M5,3 L19,12 L5,21 Z", _LS("Stress", "GpuStressLabel"), "GreenButtonStyle");
                if (FindName("GpuStressIndicator") is Border gi) gi.Visibility = Visibility.Collapsed;
            }
            if (ramDiskOn)
            {
                // Non-blocking — see the comment in PsuStressService.Stop().
                _psuStress.Stop();
            }
            if (FindName("RamStressIndicator") is Border ri) ri.Visibility = Visibility.Collapsed;
            if (FindName("DiskStressIndicator") is Border di) di.Visibility = Visibility.Collapsed;
            SetStressButtonState(BtnMaxLoad, TxtBtnMaxLoad,
                "M13,2 L3,14 H12 L11,22 L21,10 H12 L13,2Z", "Max Load", "GreenButtonStyle");
            ShowToast(_LS("Stress", "MaxLoadStopped"), "", 2000);
            SetNavTaskBadge("TaskBadgeStress", _cpuStress.Running || _gpuStress.IsRunning);
            UpdateStressBanner();
        }

        private void StartMaxLoad()
        {
            if (_cpuStress.Running || _gpuStress.IsRunning || _psuStress.IsRunning) return;
            // Start CPU + GPU + RAM + Disk
            // the intensity chosen in the bar (Endurance 80 % / Standard 100 %); two threads stay free: one for the program,
            // one for the RAM and disk work
            _cpuStress.IntensityPct = _stressIntensityPct;
            _cpuStress.Start(Environment.ProcessorCount, reserveCores: 2);
            SetStressButtonState(BtnStressCpu, TxtBtnStressCpu,
                "M6,6 H18 V18 H6 Z",
                _LS("Stress", "StopCpuStress"), "RedButtonStyle", fillIcon: true);
            if (FindName("CpuStressIndicator") is Border ci2) ci2.Visibility = Visibility.Visible;

            _gpuStress.Start();
            _gpuStressUiRunning = true;
            SetStressButtonState(BtnStressGpu, TxtBtnStressGpu,
                "M6,6 H18 V18 H6 Z",
                _LS("Stress", "StopGpuStress"), "RedButtonStyle", fillIcon: true);
            if (FindName("GpuStressIndicator") is Border gi2) gi2.Visibility = Visibility.Visible;

            _psuStress.Start();
            ApplyStressAutoStopIfNeeded();

            SetStressButtonState(BtnMaxLoad, TxtBtnMaxLoad,
                "M6,6 H18 V18 H6 Z",
                "Stop Max Load", "RedButtonStyle", fillIcon: true);

            ShowToast(_LS("Stress", "MaxLoadActiveWarning"),
                "🔥", 5000, ToastKind.Warning);
            SetNavTaskBadge("TaskBadgeStress", _cpuStress.Running || _gpuStress.IsRunning);
            UpdateStressBanner();
        }

        /// <summary>
        /// Asks how long a Turbo change lasts: -1 = cancelled, 0 = only while the program is open,
        /// 1 = permanent (stays after closing too).
        /// </summary>
        internal int AskTurboPersistence() => AskPowerPersistence(
            LanguageService.S("Stress", "TurboKeepMsg"), LanguageService.S("Stress", "TurboKeepTitle"));

        /// <summary>The same question for any processor power setting: -1 = cancelled, 0 = only while open, 1 = permanent.</summary>
        internal int AskPowerPersistence(string message, string title)
        {
            return AppDialog.Choose(
                message,
                title,
                LanguageService.S("Common", "Cancel"),
                LanguageService.S("Stress", "TurboKeepSession"),
                LanguageService.S("Stress", "TurboKeepPermanent"));
        }

        /// <summary>After a change: temporary → the original copy stays; permanent → the copy is removed.</summary>
        internal static void FinishTurboChange(int persistence, string what)
        {
            if (persistence == 1)
            {
                SMDWin.Services.TurboRestore.Clear();
                SMDWin.Services.ToolActivityLog.Add("Turbo Boost", what + " (permanent)", "info");
            }
            else
            {
                SMDWin.Services.TurboRestore.ClearIfBackToOriginal();
                SMDWin.Services.ToolActivityLog.Add("Turbo Boost", what + " (until SMD Win closes)", "info");
            }
        }

        internal void ToggleTurbo_Click(object sender, RoutedEventArgs e)
        {
            var visBtn = FindName("BtnToggleTurbo") as System.Windows.Controls.Button;
            var visTxt = FindName("TxtBtnTurbo") as System.Windows.Controls.TextBlock;
            try
            {
                _turbo.RefreshFromSystem();
                int keep = AskTurboPersistence();
                if (keep < 0) return;
                if (keep == 0) SMDWin.Services.TurboRestore.RememberOriginalIfNeeded();

                if (_turbo.IsOff)
                {
                    _turbo.SetOn();
                    AppLogger.Info("Turbo Boost: re-enabled ({0})", keep == 1 ? "permanent" : "until close");
                    FinishTurboChange(keep, "turned on");
                }
                else
                {
                    _turbo.SetOff();
                    AppLogger.Info("Turbo Boost: disabled, 99% ({0})", keep == 1 ? "permanent" : "until close");
                    FinishTurboChange(keep, "turned off");
                }
                string label = LanguageService.S("Stress", _turbo.IsOff ? "TurboOff" : "TurboOn");
                if (TxtBtnTurbo != null) TxtBtnTurbo.Text = label;
                if (visTxt      != null) visTxt.Text      = label;
                UpdateTurboButton(!_turbo.IsOff);
                if (visBtn != null)
                    visBtn.Style = (System.Windows.Style)TryFindResource("OutlineButtonStyle");
            }
            catch (Exception ex)
            {
                AppDialog.Show(string.Format(LanguageService.S("Msg", "AdminRequiredFmt"), ex.Message), "Turbo Boost");
                try { _turbo.RefreshFromSystem(); UpdateTurboButton(!_turbo.IsOff); } catch (Exception ex2) { AppLogger.Debug(ex2.Message); }
            }
        }

        private void InitTurboButtonState()
        {
            try
            {
                _turbo.RefreshFromSystem();   // the real state from Windows, not the "on" assumption
                bool isOn = !_turbo.IsOff;
                if (BtnTurbo == null) return;
                if (TxtBtnTurbo != null) TxtBtnTurbo.Text = isOn ? LanguageService.S("Stress", "TurboOn") : LanguageService.S("Stress", "TurboOff");
                UpdateTurboButton(isOn);
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }
        }
    }
}
